  (A:SPOILERS HANDLE POSITION,percent) 0.05 < (A:SPOILERS HANDLE POSITION,percent) 99.95 > ||
  if{
    (L:VSTOLAirbrakesDeployed,bool) ! (>L:VSTOLAirbrakesDeployed,bool)
